#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long max_so_far, curr_max;
    scanf("%lld", &max_so_far);
    curr_max = max_so_far;
    for (int i = 1; i < n; i++) {
        long long x;
        scanf("%lld", &x);
        curr_max = (x > curr_max + x) ? x : (curr_max + x);
        if (curr_max > max_so_far) max_so_far = curr_max;
    }
    printf("%lld\n", max_so_far);
    return 0;
}
